import { booleanAttribute, ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, OnChanges, Output, SimpleChanges } from '@angular/core';
import { factdata, factIssues, factlinkfiles } from '../../../../../shared/interfaces/fact.interface';
import { CommonModule } from '@angular/common';
import { SourceCardComponent } from '../../../../../shared/components/source-card/source-card.component';
import { SelectedIssuesComponent } from '../../../../../shared/components/issues/selected-issues/selected-issues.component';
import { FACTFROM, myTeamUsers, toolEvents } from '../../../../interfaces/pdf.interface';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { AvatarComponent } from '../../../../../shared/components/avatar/avatar.component';
import { SecureStorageService } from '../../../../../core/services/storage/secure-storage.service';
import { FactboxComponent } from '../../../facts/factbox/factbox.component';
import { navigateModeType } from '../../../../../userpanel/interfaces/navigate.interface';
import { MatTooltipModule } from '@angular/material/tooltip';
import { DateShowComponent } from "../../../../../marking/components/fact/date-show/date-show.component";
import { TranslateModule } from '@ngx-translate/core';
import { ErrorHandlerUtil } from '../../../../../userpanel/utility/error-handler.util';

@Component({
  selector: 'factcard',
  standalone: true,
  imports: [SourceCardComponent, SelectedIssuesComponent, ButtonComponent, IconComponent, CommonModule, AvatarComponent, FactboxComponent, MatTooltipModule, DateShowComponent, TranslateModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './factcard.component.html',
  styleUrl: './factcard.component.scss'
})
export class FactcardComponent implements OnInit, OnChanges {

  @Input() cFFrom: FACTFROM = 'RT';

  @Input() isFactLink: boolean = false;
  @Input() viewmode: string = 'M';
  nUserid: string;
  @Input() data: factdata = {} as factdata;

  @Output() onCardEvent = new EventEmitter<toolEvents>();

  jTexts: string[] = [];
  date1: string;
  date2: string;

  @Input() isLight: boolean = false;
  @Input() quickfact: boolean = false;
  @Input() issueList: factIssues[] = [];
  @Input() filelinks: factlinkfiles[] = [];
  @Input() userList: myTeamUsers[] = [];
  @Input({ transform: booleanAttribute }) isnavigate: boolean = false;
  @Input({ transform: booleanAttribute }) iscontact: boolean = false;
  @Input() showavatar: boolean = false;
  @Input() nohover: boolean = false;
  @Input() nFSid: string;
  @Input() type: string = '';
  @Output() OnView: EventEmitter<unknown> = new EventEmitter();
  @Input() selectedMode: navigateModeType;

  constructor(private readonly cdr: ChangeDetectorRef, private readonly scureStorage: SecureStorageService) {}


  ngOnChanges(changes: SimpleChanges): void {
    if (changes['filelinks']) {
      this.filelinks = changes['filelinks'].currentValue;
    }

    if (changes['issueList'] || changes['filelinks'] || changes['data']) {
      this.cdr.detectChanges();
    }
  }

  ngOnInit(): void {
    void this.init();
  }

  private async init(): Promise<void> {
    try {
      this.nUserid = await this.scureStorage.getUserId();
      this.jTexts = this.data.jTexts || [];

      if (this.data?.jDate) {
        // keep date parsing in handleData if required
      }
    } catch (error: unknown) {
      const errMsg = ErrorHandlerUtil.getErrorMessage(error);
      throw new Error(errMsg);
    } finally {
      this.cdr.detectChanges();
    }
  }


  public getDetail(type: string): void {
    this.onCardEvent.emit({ event: 'VIEW', data: type });
  }

  public deleteTask(): void {
    this.onCardEvent.emit({ event: 'DELETE', data: '' });
  }

  public editTask(): void {
    this.onCardEvent.emit({ event: 'EDIT', data: '' });
  }

  public OnViewEvent(x: unknown): void {
    this.OnView.emit(x);
  }

  public handleData(): void {
    try {
      this.jTexts = this.data.jTexts || [];
      if (this.data?.jDate) {
        this.date1 = this.data.jDate.date1 || '';
        this.date2 = this.data.jDate.date2 || '';
      }
    } catch (error: unknown) {
      const errMsg = ErrorHandlerUtil.getErrorMessage(error);
      throw new Error(errMsg);
    }
  }

  public OpenFactLink(event: Event | { type?: string } | null, filedata: unknown): void {
    const evtType = (event as { type?: string } | null)?.type ?? null;
    this.OnView.emit({ event: evtType, data: filedata });
  }

}